-- Baller Connection v3 core schema (D1 / SQLite). Generated by scripts/gen-schema.ts, then committed.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS families (
  id TEXT PRIMARY KEY,
  parent_name TEXT NOT NULL,
  email TEXT,
  deleted_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_families_email ON families(email);
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT UNIQUE,
  username TEXT UNIQUE,
  role TEXT NOT NULL,
  family_id TEXT REFERENCES families(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  player_id TEXT REFERENCES players(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  active INTEGER NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);
CREATE INDEX IF NOT EXISTS idx_users_family_id ON users(family_id);
CREATE TABLE IF NOT EXISTS players (
  id TEXT PRIMARY KEY,
  family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  name TEXT NOT NULL,
  age INTEGER,
  position TEXT,
  tier TEXT NOT NULL,
  state TEXT NOT NULL,
  state_since TEXT NOT NULL,
  paused_from TEXT,
  goal TEXT,
  learn_style TEXT,
  rhythm TEXT,
  canvas TEXT,
  rubric TEXT,
  next_session TEXT,
  coach_id TEXT REFERENCES users(id) ON DELETE SET NULL DEFERRABLE INITIALLY DEFERRED,
  billing TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_players_state ON players(state);
CREATE INDEX IF NOT EXISTS idx_players_coach_id ON players(coach_id);
CREATE INDEX IF NOT EXISTS idx_players_family_id ON players(family_id);
CREATE TABLE IF NOT EXISTS applications (
  id TEXT PRIMARY KEY,
  at TEXT NOT NULL,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  answers TEXT,
  tier TEXT,
  fit TEXT,
  next TEXT
);
CREATE INDEX IF NOT EXISTS idx_applications_player_id ON applications(player_id);
CREATE TABLE IF NOT EXISTS invites (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  email TEXT NOT NULL,
  token TEXT NOT NULL UNIQUE,
  code TEXT NOT NULL,
  sent_at TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_by TEXT,
  accepted_at TEXT,
  accepted_by TEXT,
  status TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_invites_player_id ON invites(player_id);
CREATE INDEX IF NOT EXISTS idx_invites_code ON invites(code);
CREATE INDEX IF NOT EXISTS idx_invites_status ON invites(status);
CREATE TABLE IF NOT EXISTS consents (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  guardian_name TEXT NOT NULL,
  user_id TEXT,
  version TEXT NOT NULL,
  text TEXT NOT NULL,
  at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_consents_player_id ON consents(player_id);
CREATE TABLE IF NOT EXISTS cycles (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  idx INTEGER,
  focus TEXT,
  start_at TEXT,
  end_at TEXT,
  status TEXT,
  template_id TEXT
);
CREATE INDEX IF NOT EXISTS idx_cycles_player_id ON cycles(player_id);
CREATE TABLE IF NOT EXISTS drills (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  reps INTEGER,
  minutes INTEGER,
  cues TEXT,
  tags TEXT,
  created_by TEXT,
  archived INTEGER
);
CREATE TABLE IF NOT EXISTS templates (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  focus TEXT,
  drill_ids TEXT,
  created_by TEXT
);
CREATE TABLE IF NOT EXISTS assignments (
  id TEXT PRIMARY KEY,
  cycle_id TEXT REFERENCES cycles(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  drill_id TEXT,
  ord REAL,
  title TEXT,
  reps INTEGER,
  minutes INTEGER,
  cues TEXT,
  status TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_assignments_player_id ON assignments(player_id);
CREATE INDEX IF NOT EXISTS idx_assignments_cycle_id ON assignments(cycle_id);
CREATE TABLE IF NOT EXISTS submissions (
  id TEXT PRIMARY KEY,
  assignment_id TEXT REFERENCES assignments(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  reps_done INTEGER,
  reflection TEXT,
  link_url TEXT,
  at TEXT NOT NULL,
  due_by TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_submissions_player_id ON submissions(player_id);
CREATE INDEX IF NOT EXISTS idx_submissions_due_by ON submissions(due_by);
CREATE TABLE IF NOT EXISTS reviews (
  id TEXT PRIMARY KEY,
  submission_id TEXT REFERENCES submissions(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  decision TEXT,
  feedback TEXT,
  at TEXT,
  reviewer_id TEXT,
  status TEXT,
  signed_off_by TEXT,
  signed_off_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_reviews_player_id ON reviews(player_id);
CREATE INDEX IF NOT EXISTS idx_reviews_status ON reviews(status);
CREATE TABLE IF NOT EXISTS messages (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  sender TEXT,
  author_id TEXT,
  text TEXT,
  link_url TEXT,
  at TEXT,
  due_by TEXT,
  answered INTEGER,
  read_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_messages_player_id ON messages(player_id);
CREATE INDEX IF NOT EXISTS idx_messages_answered ON messages(answered);
CREATE TABLE IF NOT EXISTS habits (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  date TEXT,
  habit TEXT
);
CREATE INDEX IF NOT EXISTS idx_habits_player_id_date ON habits(player_id, date);
CREATE TABLE IF NOT EXISTS milestones (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  milestone TEXT,
  at TEXT
);
CREATE INDEX IF NOT EXISTS idx_milestones_player_id ON milestones(player_id);
CREATE TABLE IF NOT EXISTS digests (
  id TEXT PRIMARY KEY,
  player_id TEXT NOT NULL REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  week TEXT,
  text TEXT,
  status TEXT,
  approved_at TEXT,
  approved_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_digests_player_id_week ON digests(player_id, week);
CREATE TABLE IF NOT EXISTS meetings (
  id TEXT PRIMARY KEY,
  player_id TEXT REFERENCES players(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  staff_id TEXT,
  at TEXT,
  minutes INTEGER,
  kind TEXT,
  note TEXT,
  status TEXT
);
CREATE INDEX IF NOT EXISTS idx_meetings_at ON meetings(at);
CREATE INDEX IF NOT EXISTS idx_meetings_staff_id ON meetings(staff_id);
CREATE TABLE IF NOT EXISTS notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE DEFERRABLE INITIALLY DEFERRED,
  type TEXT,
  text TEXT,
  player_id TEXT,
  link TEXT,
  at TEXT,
  read_at TEXT,
  emailed_at TEXT,
  dedupe TEXT UNIQUE
);
CREATE INDEX IF NOT EXISTS idx_notifications_user_id_read_at ON notifications(user_id, read_at);
CREATE TABLE IF NOT EXISTS outbox (
  id TEXT PRIMARY KEY,
  recipient TEXT,
  subject TEXT,
  body TEXT,
  at TEXT,
  status TEXT,
  kind TEXT
);
CREATE INDEX IF NOT EXISTS idx_outbox_status ON outbox(status);
CREATE TABLE IF NOT EXISTS data_requests (
  id TEXT PRIMARY KEY,
  player_id TEXT,
  family_id TEXT,
  kind TEXT,
  requested_by TEXT,
  at TEXT,
  status TEXT,
  done_at TEXT
);
CREATE INDEX IF NOT EXISTS idx_data_requests_status ON data_requests(status);
CREATE TABLE IF NOT EXISTS events (
  id TEXT PRIMARY KEY,
  at TEXT NOT NULL,
  role TEXT,
  actor_id TEXT,
  player_id TEXT,
  type TEXT,
  from_state TEXT,
  to_state TEXT,
  detail TEXT
);
CREATE INDEX IF NOT EXISTS idx_events_at ON events(at);
CREATE INDEX IF NOT EXISTS idx_events_player_id ON events(player_id);
